package com.kai.automusic;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.widget.*;import java.util.*;
final class MusicDownloads {
 final MainActivity a; final DownloadManager dm; final android.content.SharedPreferences p;
 MusicDownloads(MainActivity a){this.a=a;dm=(DownloadManager)a.getSystemService(Context.DOWNLOAD_SERVICE);p=a.getSharedPreferences("downloads",0);}
 void show(){LinearLayout l=new LinearLayout(a);l.setOrientation(1);EditText url=new EditText(a);url.setHint("https://.../song.m4a หรือ video.mp4");url.setInputType(17);l.addView(url);EditText name=new EditText(a);name.setHint("ชื่อไฟล์ (ไม่บังคับ)");l.addView(name);CheckBox add=new CheckBox(a);add.setText("เพิ่มเข้าเพลย์ลิสต์อัตโนมัติ");add.setChecked(true);l.addView(add);TextView hint=new TextView(a);hint.setText("เก็บไฟล์ต้นฉบับ เล่นเฉพาะเสียง ไม่แปลงคุณภาพ");l.addView(hint);new AlertDialog.Builder(a).setTitle("Download Manager").setView(l).setPositiveButton("ดาวน์โหลด",(d,w)->enqueue(url.getText().toString().trim(),name.getText().toString().trim(),add.isChecked())).setNeutralButton("รายการดาวน์โหลด",(d,w)->history()).setNegativeButton("ยกเลิก",null).show();}
 void enqueue(String link,String title,boolean add){try{Uri u=Uri.parse(link);String host=u.getHost();if(!"https".equalsIgnoreCase(u.getScheme())||host==null)throw new Exception("ใช้ลิงก์ HTTPS ของไฟล์เสียง");String h=host.toLowerCase(Locale.ROOT);if(h.equals("youtu.be")||h.equals("youtube.com")||h.endsWith(".youtube.com"))throw new Exception("YouTube: กรุณานำเข้าไฟล์ที่ดาวน์โหลดอย่างได้รับอนุญาตก่อน");String file=u.getLastPathSegment();if(file==null||!file.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|m4a|aac|wav|flac|ogg|opus|mp4|webm|mkv|3gp|amr)$"))throw new Exception("ต้องเป็นลิงก์ไฟล์เสียงหรือวิดีโอโดยตรง");String ext=file.substring(file.lastIndexOf('.'));if(!title.isEmpty())file=title+ext;file=file.replaceAll("[^\\p{L}\\p{N}._ -]","_");file=System.currentTimeMillis()+"_"+file;DownloadManager.Request r=new DownloadManager.Request(u).setTitle(file).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationInExternalFilesDir(a,Environment.DIRECTORY_MUSIC,file);long id=dm.enqueue(r);p.edit().putBoolean("job"+id,add).apply();Toast.makeText(a,"เริ่มดาวน์โหลด",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}}
 void scan(){for(String k:new HashSet<>(p.getAll().keySet())){if(!k.startsWith("job"))continue;try{long id=Long.parseLong(k.substring(3));try(Cursor c=dm.query(new DownloadManager.Query().setFilterById(id))){if(c==null||!c.moveToFirst())continue;int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(status==DownloadManager.STATUS_SUCCESSFUL){String u=c.getString(c.getColumnIndexOrThrow(DownloadManager.COLUMN_LOCAL_URI));if(u!=null&&!hasAudio(u)){p.edit().remove(k).putString("done"+id,"ไฟล์ไม่มีเสียงหรือเปิดไม่ได้").apply();continue;}if(u!=null&&p.getBoolean(k,false)&&!a.songs.contains(u)){a.songs.add(u);a.save();}p.edit().remove(k).putString("done"+id,u).apply();}else if(status==DownloadManager.STATUS_FAILED){p.edit().remove(k).putString("done"+id,"ดาวน์โหลดไม่สำเร็จ").apply();}}}catch(Exception ignored){}}}
 boolean hasAudio(String u){android.media.MediaExtractor e=new android.media.MediaExtractor();try{e.setDataSource(a,Uri.parse(u),null);for(int i=0;i<e.getTrackCount();i++){String mime=e.getTrackFormat(i).getString(android.media.MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("audio/"))return true;}return false;}catch(Exception ex){return false;}finally{e.release();}}
 void history(){scan();StringBuilder b=new StringBuilder();for(String k:p.getAll().keySet()){if(k.startsWith("job"))b.append("กำลังดาวน์โหลด #").append(k.substring(3)).append('\n');else if(k.startsWith("done"))b.append(p.getString(k,"")).append('\n');}new AlertDialog.Builder(a).setTitle("รายการดาวน์โหลด").setMessage(b.length()==0?"ยังไม่มีรายการ":b.toString()).setPositiveButton("ปิด",null).show();}
}